// Match the whole of text against the glob pattern. Characters are
// Unicode code points (as returned by chars) and matching is case-sensitive.
// Pattern syntax:
//   ?       matches exactly one character.
//   *       matches any sequence of characters, including the empty one.
//   [set]   matches exactly one character that is in the set; [!set]
//           matches exactly one character that is not in the set. In a set,
//           x-y is an inclusive range of code points; a ] that comes first
//           (right after [ or [!) is a literal member; a - that comes first
//           or last is a literal member; ^ and \ have no special meaning.
//   \c      (backslash then any character c) matches c literally.
//   any other character matches itself.
// The pattern is invalid if a [ has no closing ], if it ends in a lone
// backslash, or if a range has its start after its end (as in [z-a]); for an
// invalid pattern return None, whatever the text. Otherwise return Some(true)
// or Some(false). Patterns and texts may be hundreds of characters long with
// many stars, so the running time must be polynomial (no exponential
// backtracking).
// Examples:
//   wildcard_match("*.py", "main.py") == Some(true)
//   wildcard_match("a[b", "ab") == None
fn wildcard_match(pattern: Str, text: Str) -> Option[Bool] {
  let tokens = parse_glob(pattern)?;
  let t = chars(text);
  let mut p = 0;
  let mut i = 0;
  let mut star = -1;
  let mut star_i = 0;
  while i < len(t) {
    if p < len(tokens) && tokens[p] != Star && tok_matches(tokens[p], t[i]) {
      p = p + 1;
      i = i + 1;
    } else if p < len(tokens) && tokens[p] == Star {
      star = p;
      star_i = i;
      p = p + 1;
    } else if star >= 0 {
      // let the last star absorb one more character and retry
      star_i = star_i + 1;
      p = star + 1;
      i = star_i;
    } else {
      return Some(false);
    }
  }
  while p < len(tokens) && tokens[p] == Star {
    p = p + 1;
  }
  Some(p == len(tokens))
}

type Tok = Star | AnyChar | Lit(c: Str) | CharSet(neg: Bool, items: List[(Str, Str)])

fn tok_matches(tok: Tok, c: Str) -> Bool {
  match tok {
    Star => true,
    AnyChar => true,
    Lit(x) => x == c,
    CharSet(neg, items) => any(items, |r| r.0 <= c && c <= r.1) != neg,
  }
}

fn parse_glob(pattern: Str) -> Option[List[Tok]] {
  let p = chars(pattern);
  let n = len(p);
  let mut out: List[Tok] = [];
  let mut i = 0;
  while i < n {
    let c = p[i];
    if c == "*" {
      out = push(out, Star);
      i = i + 1;
    } else if c == "?" {
      out = push(out, AnyChar);
      i = i + 1;
    } else if c == "\\" {
      if i + 1 >= n {
        return None;
      }
      out = push(out, Lit(p[i + 1]));
      i = i + 2;
    } else if c == "[" {
      let mut j = i + 1;
      let neg = j < n && p[j] == "!";
      if neg {
        j = j + 1;
      }
      let mut items: List[(Str, Str)] = [];
      let mut first = true;
      while true {
        if j >= n {
          return None;
        }
        if p[j] == "]" && !first {
          break;
        }
        first = false;
        if j + 2 < n && p[j + 1] == "-" && p[j + 2] != "]" {
          if p[j] > p[j + 2] {
            return None;
          }
          items = push(items, (p[j], p[j + 2]));
          j = j + 3;
        } else {
          items = push(items, (p[j], p[j]));
          j = j + 1;
        }
      }
      out = push(out, CharSet(neg, items));
      i = j + 1;
    } else {
      out = push(out, Lit(c));
      i = i + 1;
    }
  }
  Some(out)
}
